Method.Implementation:

	 try{
		do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		$$$TRACE("Service " _ ..TuxedoService)		
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrStringAddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)		
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while Creating Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	Quit status

	 #DIM status AS %Status
	 set status = $$$OK
	 #dim exceptionString As %String="JAVAEXCEPTION"
	 $$$TRACE("IHC.ITF.ITFCOMMON.CDR.XMLProxyTuxedoServiceOperation..Inside OnMessage method")
	 try{
		 if (..CheckObject() '= $$$OK) {
		 	$$$TRACE("**** Object does not exists ****")
		 	// Try to re intialize
		 	set result = ..OnInit()
			if (result '= $$$OK)
			{
				set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-Xmlproxy", "Store Data to MSPR failed. For : " _pRequest.StringValue_ " ; Reason: " _ result)						
				return status
			}
	 	}


		 		$$$TRACE(" Calling Tuxedo Service .."_pRequest.StringValue)

		 		set tsc = $$$OK
		 		set pResponse=##class(Ens.StringResponse).%New()
		 		Set pResponse.StringValue = ..objCdrTuxService.callAddUpdate(pRequest.StringValue)

		 		Set respData = pResponse.StringValue
		 		if (pResponse.StringValue[exceptionString){

			 	   SET ex = ##class(%Exception.General).%New("JavaException","JavaException",,
                             "pResponse.StringValue")
                   set pResponse.StringValue=""
       			   THROW ex
		 		}

		 		$$$TRACE(" Call after the Xmlproxy Call .."_respData)



	 }catch err{	
	   	 $$$TRACE("Exception in calling MSPR Add/Update: " _err.AsSystemError() _ " _ ErrData: " _ err.Data _ "; ErrCode:" _ err.Code)
	     Set status = ..ExceptionHandler(err, "OnMessage")
	 }
	 return status


$$$TRACE(" $$$$$$$$$$$$$$$ Inside OnTearDown() method...")

Set tSC = $$$OK

Try {		
	If $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		Do ..objCdrTuxService.shutdownTuxService()		
		Set ..objCdrTuxService = $$$NULLOREF
	}
}
Catch {
	Set tSC = $$$EnsSystemError
}
Set tSC = ##super()
Quit tSC
